// Original work-interest prompts. Three facets per field: activity, setting, and routine.
// These are editorial exploration questions, not validated aptitude measures.
const rows={
 creative:[['Turn an original idea into a piece an audience can experience.','Creating original work'],['Try several drafts and improve one after specific feedback.','Revising creative ideas'],['Think about how a design or story will feel to its audience.','Understanding an audience']],
 technology:[['Build or improve a digital tool that solves a useful problem.','Building useful digital tools'],['Spend time tracing why software or a device behaves unexpectedly.','Troubleshooting digital systems'],['Test small changes and keep track of what works reliably.','Testing and refining solutions']],
 health:[['Investigate a health concern and explain ways to help.','Investigating health concerns'],['Help someone understand what is happening during a care visit.','Working directly with people receiving care'],['Keep health information accurate and follow care and privacy procedures.','Handling careful health-related work']],
 business:[['Compare costs and evidence before recommending a business decision.','Evaluating business decisions'],['Discuss different needs and work toward a practical agreement.','Working through decisions with people'],['Check financial or legal details before explaining a recommendation.','Checking financial or legal evidence']],
 science:[['Gather measurements and compare them with a possible explanation.','Investigating questions with evidence'],['Stay with an investigation when the answer is still uncertain.','Exploring unanswered questions'],['Repeat a method and document the results even when the first attempt is inconclusive.','Using careful research methods']],
 building:[['Design a structure or device before it is made.','Designing things before they are built'],['Use drawings and measurements to compare possible designs.','Working through technical designs'],['Revise a design to meet safety rules and practical limits.','Balancing design and real-world constraints']],
 trades:[['Install or repair a physical system so it works properly.','Installing or repairing physical systems'],['Work with tools and materials in a workshop or at a job site.','Working with tools and materials'],['Trace a fault and check a repair using the required safety procedures.','Diagnosing faults and checking repairs']],
 services:[['Prepare an everyday service so it feels useful and welcoming.','Delivering a well-prepared service'],['Work directly with a customer to understand the result they want.','Understanding customers in person'],['Follow hygiene and preparation routines while keeping up with a busy service.','Handling practical service routines']],
 education:[['Explain an idea in a different way when someone does not understand it.','Helping people understand ideas'],['Spend time with learners who have different needs and ways of learning.','Working alongside different learners'],['Adjust an activity and give feedback when a learner gets stuck.','Adapting lessons and feedback']],
 'public-safety':[['Practise an organized response to an urgent situation.','Preparing for urgent situations'],['Stay calm while helping people who are facing a safety risk.','Helping people during safety emergencies'],['Follow approved procedures while a response team coordinates its actions.','Working within an emergency-response team']],
 'transportation-production':[['Coordinate materials and equipment so a practical workflow runs smoothly.','Keeping materials and work moving'],['Work with a team where goods are stored, moved, or produced.','Working in a physical operations setting'],['Check a practical process for delays, safety issues, and record errors.','Checking operations and safety']],
 'sales-office':[['Help someone resolve a service question or compare useful options.','Resolving service questions'],['Organize requests and information so a busy team can keep working.','Keeping an office or service organized'],['Check transactions and records carefully while responding to requests.','Keeping service records accurate']]
};
export const pathwayProfileQuestions=[0,1,2].flatMap((facet)=>Object.entries(rows).map(([family,items])=>({id:'field-profile-'+family+'-'+(facet+1),family,facet:['activity','setting','routine'][facet],prompt:items[facet][0],summary:items[facet][1],kind:'pathway',section:'Picture the everyday work'})));
export const pathwayQuestionsFor=family=>pathwayProfileQuestions.filter(q=>q.family===family);
export function pathwayProfileEvidence(s,family){const items=pathwayQuestionsFor(family).map(q=>({...q,value:s.profileJourney?.fieldPreferences?.[q.id]})),rated=items.filter(q=>Number.isInteger(q.value)),likes=rated.filter(q=>q.value>=4),concerns=rated.filter(q=>q.value<=2);return {items,rated,likes,concerns,mean:rated.length?rated.reduce((n,q)=>n+q.value,0)/rated.length:null,complete:items.every(q=>[1,2,3,4,5,'untried'].includes(q.value)),confirmed:rated.length>=2&&likes.length>=2};}
